// Assemble the triage prompt. Two passes in one call: the hard
// disqualifier gate first, then capability overlap scoring — the order
// matters, because a failed hard gate makes the score irrelevant.
//
// Everything Caravann-specific comes from the context endpoint, so
// editing the sector map in Settings changes the verdicts. Nothing about
// Caravann is hardcoded here.

const config = $('Config').first().json;
const context = $('Load triage context').first().json;
const payload = config.payload;

// Either the extracted PDF text or the raw text posted in.
const extracted = $input.first().json;
const documentText = extracted.text || payload.document_text || '';

if (!documentText.trim()) {
  throw new Error('No document text — document_url produced no extractable text and no document_text was supplied.');
}

const profile = context.org_profile || {};
const sectors = context.sector_experience || [];
const portalRules = context.portal_rules || [];

const profileBlock = [
  `Bilingual staff: ${profile.bilingual_staff ? 'yes' : 'no'}`,
  `Media production capability: ${profile.media_production_capable ? 'yes' : 'no'}`,
  `PR capability: ${profile.pr_capable ? 'yes' : 'no'}`,
  `Office locations: ${(profile.office_locations || []).join(', ') || 'none recorded'}`,
  `Consultant locations: ${(profile.consultant_locations || []).join(', ') || 'none recorded'}`,
  `Certifications: ${(profile.certifications || []).join(', ') || 'none recorded'}`,
  `Set-aside status: ${(profile.set_aside_status || []).join(', ') || 'none'}`,
  `Insurance carried: ${profile.insurance_coverage || 'not recorded'}`,
  `Facilitating elected or appointed bodies: ${profile.governing_body_experience || 'not recorded'}`,
  profile.notes ? `Notes: ${profile.notes}` : null,
].filter(Boolean).join('\n');

// What Caravann does, as distinct from where it has been. Without this the only
// evidence for "have you done this kind of work?" was a sector count, so a
// solicitation asking for culture transformation from a firm whose stated core
// service is culture transformation scored as a thin adjacent guess.
const cap = profile.capabilities || {};
const capabilityBlock = [
  cap.functional_areas?.length ? `Functional areas: ${cap.functional_areas.join(', ')}` : null,
  cap.key_capabilities?.length ? `Key capabilities: ${cap.key_capabilities.join(', ')}` : null,
  cap.subject_areas?.length ? `Subject areas: ${cap.subject_areas.join(', ')}` : null,
].filter(Boolean).join('\n') || 'none recorded';

const sectorBlock = sectors.length
  ? sectors.map(s => `- ${s.sector}: ${s.years_experience ?? '?'} years, ${s.engagement_count ?? '?'} engagements${s.notes ? ` (${s.notes})` : ''}`).join('\n')
  : 'No sector experience recorded yet.';

const portalBlock = portalRules.length
  ? portalRules.map(r => `- ${r.portal_name}: ${r.rule_text}`).join('\n')
  : 'None recorded.';

const system = `You are the qualification engine for Caravann Consulting's RFP bid desk.

You read a full government solicitation and return a structured verdict. Caravann's principal reads your verdict INSTEAD OF the document, so a miss costs them either a wasted week or a lost bid. Be exact and be honest about uncertainty.

HOW TO JUDGE

1. HARD GATE FIRST. Walk every stated requirement in the solicitation. For each, decide whether Caravann meets it, using ONLY the profile below — never assume a capability that is not recorded.
   - Requirement worded as REQUIRED/MUST/SHALL and not met -> result "fail", is_required true. Any such failure forces status "no_go".
   - Requirement worded as PREFERRED/DESIRED/SHOULD and not met -> result "fail", is_required false. This LOWERS the score but never by itself forces no_go.
   - Requirement Caravann meets -> "pass". Requirement that does not apply -> "not_applicable".
   - Requirement where the profile simply DOES NOT SAY either way -> result "unclear".
     This is the important one. "fail" means the profile shows Caravann does NOT
     meet it — no behavioral health experience, no California office. "unclear"
     means the profile is silent, so you cannot tell. Do not use "fail" for
     silence: a required fail closes the bid permanently, while "unclear" asks a
     human the one question that would settle it. When you are genuinely unsure
     which applies, choose "unclear" — a wrongly closed bid costs a contract, a
     wrongly raised question costs five minutes. Say in the note exactly what
     evidence would resolve it.
   - But "unclear" is for SILENCE, not for imperfect wording. If the profile
     records something that plainly satisfies the requirement, that is a "pass",
     even if the solicitation phrases it differently. "Five years facilitating
     strategic planning for public agencies" is met by a sector map showing 12
     years and 34 public-agency engagements — read the profile for what it means,
     not for a keyword match. Marking a requirement the profile answers as
     "unclear" is just as wrong as marking a silent one "fail": it buries the
     handful of questions that genuinely need a human in a pile that does not.
   - State each requirement ONCE, in the solicitation's own words, without a
     trailing "required"/"must be provided". Never list the same underlying
     requirement twice.

2. THEN SCORE by classifying each dimension below. Do NOT invent an overall number — the percentage is computed from these classifications, and any total you volunteer is discarded. Pick the level whose description actually fits, and add a one-line note saying what in the profile or the solicitation decided it.

RUBRIC
  sector_depth — Sector depth
    How deep is Caravann's recorded experience in the sector this solicitation sits in? Judge only against the sector experience map — never assume depth that is not recorded.
      "none" — No recorded experience in this sector
      "thin" — Some experience, but shallow for the scope
      "adequate" — Solid, comparable experience
      "strong" — Squarely the work Caravann already does

  comparable_engagements — Comparable engagements
    How many comparable engagements has Caravann delivered — same kind of work, similar client type and scale? Judge \"same kind of work\" against the stated services above as well as the sector map: a solicitation asking for something on that list is core business, not an adjacent guess.
      "none" — None on record
      "few" — One or two
      "several" — Three to five
      "many" — Six or more

  geographic_fit — Geographic fit
    Does the solicitation need people on the ground, and can Caravann provide them from its recorded office and consultant locations?
      "none" — Local presence needed and absent
      "remote_ok" — Deliverable remotely, or travel is workable
      "local" — Caravann already has presence in the area

  timeline — Timeline
    Is there enough runway between now and the submission deadline, and is the delivery schedule the solicitation sets out achievable?
      "infeasible" — Cannot realistically be met
      "tight" — Achievable but demanding
      "comfortable" — Comfortable runway

  budget_vs_effort — Budget against effort
    Does the stated budget cover the effort the scope implies? If no budget is named anywhere, judge on scope alone and say so in the note.
      "underfunded" — Budget will not cover the work
      "adequate" — Budget matches the effort
      "generous" — Budget is comfortable for the scope
3. VERDICT. "go" = clears every hard gate and scores well. "no_go" = fails a required gate, or the overlap is too thin to be worth the hours. "maybe" = clears the hard gates but something real is unresolved (thin sector depth, tight timeline, budget that may not cover the effort). Use "maybe" honestly — a false "go" costs a wasted week, and a false "no_go" costs a winnable contract.

4. BUDGET. Read the not-to-exceed / contract value from the SOLICITATION TEXT ONLY. Never estimate, never infer from scope size. If the document names no figure anywhere, set budget_amount null and budget_source "none_listed". If the figure came from an attached Q&A rather than the RFP body, use "qa_document".

5. GAPS. Everything Caravann is short on for THIS solicitation, tagged by type. This is a teaming shopping list — it must be specific enough that a reader knows what a partner firm would need to bring. "Lacks behavioral health experience" is useful; "lacks experience" is not.

6. COMPLIANCE. Every rule that can disqualify a bid on a technicality: due date, question deadline, page and section limits, fonts and sizes, required sections, submission method and file-count rules, insurance, and evaluation rubric weights. Put real dates in due_at as ISO 8601. Submission mechanics matter as much as deadlines — a three-reference requirement with one upload slot belongs here.

7. QUESTIONS. Draft strategic questions for the public memo lane, and one direct request to the named contact for an incumbent or prior winning proposal in the incumbent_request lane. NEVER draft a question the solicitation already answers — check first. Keep the memo short enough to be answered inside the window.

Write verdict_why and verdict_why_not as plain prose a busy principal can scan. No hedging filler, no restating the requirement list.`;

const user = `CARAVANN ELIGIBILITY PROFILE\n${profileBlock}\n\nWHAT CARAVANN DOES (its own stated services — weigh this alongside sector counts when judging whether it has done this kind of work)\n${capabilityBlock}\n\nCARAVANN SECTOR EXPERIENCE\n${sectorBlock}\n\nKNOWN PORTAL RULES (fold any that apply into the compliance checklist)\n${portalBlock}\n\n---\n\nSOLICITATION TEXT\n\n${documentText}`;

// Read the document several times over. A single sample cannot tell a real
// no-go from a bad run: five reads of one identical document scored 55, 82,
// 86, 88 and 90, and the 55 would have binned a winnable bid. The downstream
// node takes the median, so one bad read cannot decide anything.
const runs = Number(config.triage_runs) || 3;
return Array.from({ length: runs }, (_, run) => ({
  json: { system, user, model: config.model, bid_desk_url: config.bid_desk_url, payload, run },
}));

// Reconcile several independent reads of the same solicitation into one verdict.
//
// Why this exists: five runs of a byte-identical document returned scores of
// 55, 82, 86, 88 and 90. Four of those are go-or-maybe; the 55 is simply a bad
// read, and it would have dropped a winnable bid into the no-go folder — the
// one place nobody looks again. A single sample cannot tell a real no-go from
// a bad morning.
//
// So the workflow now reads the document N times and this node reconciles:
//
//   score        median — one outlier cannot move it
//   compliance   union across runs, deduped. Missing a page limit loses a bid;
//                an extra checklist line costs nothing. Recall is the weak axis
//                on every frontier model, so bias toward keeping.
//   gate checks  from the median run, plus any REQUIRED failure that at least
//                two runs agree on. A false failure here kills a winnable bid,
//                so a lone dissenting run does not get to close the door.
//   everything   from the median run, so the prose matches the number it
//                explains rather than being stitched from three narratives.

const prompt = $('Build triage prompt').first().json;
const payload = prompt.payload;

const parsed = [];
const failures = [];

for (const item of $input.all()) {
  const response = item.json;
  const raw = response?.choices?.[0]?.message?.content;
  if (!raw) {
    failures.push(response?.choices?.[0]?.error?.message || 'no content returned');
    continue;
  }
  try {
    parsed.push(typeof raw === 'string' ? JSON.parse(raw) : raw);
  } catch (e) {
    failures.push(`unparseable JSON: ${e.message}`);
  }
}

if (parsed.length === 0) {
  throw new Error(`All ${$input.all().length} triage runs failed: ${failures.join(' | ')}`);
}

// ── vote on each dimension ──────────────────────────────────────────────────
// The model no longer returns a number; it classifies five anchored dimensions
// and the bid desk does the arithmetic. That makes reconciliation a vote rather
// than an average: "strong, strong, adequate" has an obvious winner, where
// "78, 90, 90" only ever had a median.
const DIMENSIONS = ['sector_depth', 'comparable_engagements', 'geographic_fit', 'timeline', 'budget_vs_effort'];

const rubric = {};
const dissent = {};

for (const key of DIMENSIONS) {
  const votes = new Map();
  for (const run of parsed) {
    const answer = run.score_rubric?.[key];
    if (!answer?.level) continue;
    const entry = votes.get(answer.level) || { count: 0, answer };
    entry.count += 1;
    votes.set(answer.level, entry);
  }
  if (votes.size === 0) continue;

  // Most votes wins. On a tie the runs genuinely disagree, so take the first —
  // and record the split so the disagreement is visible rather than averaged
  // into a number nobody can question.
  const ranked = [...votes.entries()].sort((a, b) => b[1].count - a[1].count);
  rubric[key] = ranked[0][1].answer;
  if (ranked.length > 1) {
    dissent[key] = ranked.map(([level, v]) => `${level}×${v.count}`).join(', ');
  }
}

// Kept only so the spread stays visible on the card and we can tell over time
// whether the model is steadying. It no longer decides anything.
const scored = parsed
  .filter((v) => typeof v.score_percent === 'number' && Number.isFinite(v.score_percent))
  .sort((a, b) => a.score_percent - b.score_percent);
const samples = scored.map((v) => Math.round(v.score_percent));
const spread = samples.length > 1 ? samples[samples.length - 1] - samples[0] : 0;

// The narrative comes from whichever run best matches the agreed classification,
// so the prose explains the score that was actually assigned.
const agreement = (run) => DIMENSIONS.filter((k) => run.score_rubric?.[k]?.level === rubric[k]?.level).length;
const median = [...parsed].sort((a, b) => agreement(b) - agreement(a))[0];

// ── union the things it is expensive to miss ────────────────────────────────
const norm = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').replace(/[^a-z0-9 ]/g, '').trim();

/** Every distinct entry across all reads, first spelling wins. Missing a
 *  compliance rule loses a bid; a spare line costs nothing, so the union is
 *  deliberately generous and the dedupe below tightens it back up. */
function unionBy(lists, keyOf) {
  const seen = new Map();
  for (const list of lists) {
    for (const entry of list || []) {
      const key = keyOf(entry);
      if (key && !seen.has(key)) seen.set(key, entry);
    }
  }
  return [...seen.values()];
}

// Three reads phrase the same obligation three different ways, and an exact
// match keeps all three. Real output from one solicitation:
//
//   "20-page limit" / "20-page proposal limit" / "20-page maximum proposal length"
//   "Proposal due date" / "Proposal due date/time" / "Proposal submission deadline"
//
// A checklist that lists one rule three times is worse than one that lists it
// once - it reads as three things to satisfy and buries the items that are
// genuinely separate.
//
// Two passes, because compliance labels and requirement sentences fail
// differently. Dated items are matched on the date itself, which is exact and
// needs no guessing: three entries all due 2026-08-27 in the deadline category
// are one deadline. Undated ones fall back to comparing words, after collapsing
// the synonym families that cause most of the noise.
const FILLER = new Set(['required','require','requires','must','shall','should','be','is','are','the','a','an','of','to','and','or','in','for','with','at','least','minimum','provide','provided','submit','have','has','per','via','any','all']);
const SYNONYM = new Map([
  ['maximum','limit'], ['max','limit'], ['length','limit'], ['cap','limit'], ['page','pg'], ['pages','pg'],
  ['deadline','due'], ['date','due'], ['time','due'], ['datetime','due'], ['submission','due'], ['deliver','due'],
  ['coverage','insurance'], ['liability','insurance'],
  ['changes','revision'], ['change','revision'], ['revised','revision'], ['categories','revision'], ['scoring','revision'],
]);
const canon = (w) => SYNONYM.get(w) || w;
const tokens = (s) => new Set(norm(s).split(' ').map(canon).filter((w) => w && !FILLER.has(w)));
// Two tokens is enough once fillers and synonyms are gone: "20-page limit"
// reduces to {pg, limit}, and demanding three would leave it unmergeable, which
// is exactly the case this is here to fix.
const subsumes = (a, b) => b.size >= 2 && b.size <= a.size && [...b].every((w) => a.has(w));

/**
 * How much two token sets overlap, 0 to 1 (Jaccard).
 *
 * Needed for gap items, which subset matching cannot touch. Compliance labels
 * are terse and near-identical between reads, so one contains the other. Gaps
 * are free prose and each read writes them fresh:
 *
 *   "No Oregon Business Registry number on file; must be obtained before..."
 *   "Oregon Business Registry number is not confirmed on file; must be..."
 *
 * Neither contains the other - one says "no ... obtained", the other "not ...
 * confirmed" - but they share five of nine meaningful words and are plainly the
 * same gap. Overlap catches that where containment cannot.
 */
function similarity(a, b) {
  if (a.size === 0 || b.size === 0) return 0;
  let shared = 0;
  for (const w of a) if (b.has(w)) shared++;
  return shared / (a.size + b.size - shared);
}

/** Fold near-duplicates onto the first spelling seen, keeping the longer
 *  wording since it is usually the more complete statement. `sameThing` is an
 *  optional exact test that runs before the word comparison. */
function dedupeRequirements(entries, textOf, sameThing, overlap = 0) {
  const kept = [];
  for (const entry of entries) {
    const t = tokens(textOf(entry));
    const match = kept.find(
      (k) =>
        (sameThing && sameThing(k, entry)) ||
        subsumes(k._t, t) ||
        subsumes(t, k._t) ||
        // Half the meaningful words in common is a high bar for prose written
        // independently three times, and low enough to catch the restatements.
        (overlap > 0 && similarity(k._t, t) >= overlap)
    );
    if (!match) { kept.push({ ...entry, _t: t }); continue; }
    if (String(textOf(entry) || '').length > String(textOf(match) || '').length) {
      Object.assign(match, entry, { _t: match._t });
    }
  }
  return kept.map(({ _t, ...rest }) => rest);
}

const complianceItems = dedupeRequirements(
  unionBy(parsed.map((v) => v.compliance_items), (c) => norm(c.label)),
  (c) => c.label,
  // Same category, same date, same obligation. Exact, and it catches the
  // deadline restatements that word-matching cannot.
  (a, b) => Boolean(a.due_at) && a.due_at === b.due_at && a.category === b.category
);
// Gaps are prose, so they match on word overlap rather than containment: each
// read writes them fresh, so "No Oregon Business Registry number on file" and
// "Oregon Business Registry number is not confirmed on file" describe one gap
// while neither contains the other.
//
// Matched on content alone, deliberately ignoring gap_type. Tying it to the
// type was tried and made things worse - the reads disagree about the type of
// the very gaps that are duplicated, tagging one "certification" and the next
// "other", so requiring a type match kept both. The text is the reliable
// signal; the label is not.
const gapItems = dedupeRequirements(
  unionBy(parsed.map((v) => v.gap_items), (g) => norm(g.description)),
  (g) => g.description,
  null,
  0.42
);

// ── the gate: only unanimous agreement closes a bid ─────────────────────────
// Three reads of the same document are three chances to mistake a silence in
// the profile for a deficiency in Caravann. A majority vote picks a side on a
// 2-1 split, which is precisely the case where there is no side to pick — the
// disagreement IS the uncertainty, and burying it under a vote throws away the
// most useful signal in the run.
//
// So: every read has to independently agree a required requirement fails before
// the bid closes. Short of that it becomes "unclear", which caps the verdict at
// maybe and puts the question in front of a human. Deliberately asymmetric — a
// wrongly closed bid is a lost contract nobody notices, a wrongly raised
// question is five minutes.
const medianChecks = median.disqualifier_checks || [];
const byKey = new Map(medianChecks.map((c) => [norm(c.requirement_text), c]));

const votes = new Map();
for (const run of parsed) {
  for (const check of run.disqualifier_checks || []) {
    if (!check.is_required) continue;
    const key = norm(check.requirement_text);
    if (!key) continue;
    const entry = votes.get(key) || { fail: 0, unclear: 0, seen: 0, check };
    entry.seen += 1;
    if (check.result === 'fail') entry.fail += 1;
    if (check.result === 'unclear') entry.unclear += 1;
    votes.set(key, entry);
  }
}

for (const [key, tally] of votes) {
  const base = { ...(byKey.get(key) || tally.check), ...tally.check, is_required: true };
  if (tally.fail === parsed.length) {
    // Every read, independently, found this genuinely unmet. That closes it.
    byKey.set(key, { ...base, result: 'fail' });
  } else if (tally.fail > 0 || tally.unclear > 0) {
    const detail = tally.fail > 0 && tally.fail < tally.seen
      ? ' (' + tally.fail + ' of ' + parsed.length + ' reads called this a miss, the rest did not)'
      : '';
    byKey.set(key, {
      ...base,
      result: 'unclear',
      notes: (base.notes ? base.notes + ' ' : '') +
        'Not settled by triage' + detail + ' — confirm against the eligibility profile.',
    });
  }
}

const disqualifierChecks = dedupeRequirements([...byKey.values()], (c) => c.requirement_text).map((c) => ({
  requirement_text: c.requirement_text,
  is_required: c.is_required,
  result: c.result,
  notes: c.notes,
}));

// ── the payload ─────────────────────────────────────────────────────────────
// `status` is deliberately not sent: the bid desk recomputes the label from the
// score and the gate results, so whatever the model called it is irrelevant.
const body = {
  external_id: payload.external_id,
  title: payload.title || median.title,
  client_agency: payload.client_agency || median.client_agency,
  project_type: median.project_type,
  source: payload.source || 'manual',
  source_url: payload.source_url || payload.document_url || null,
  due_at: median.due_at,
  question_deadline_at: median.question_deadline_at,
  budget_amount: median.budget_amount,
  budget_source: median.budget_source,
  score_breakdown: rubric,
  score_samples: samples,
  verdict_why: median.verdict_why,
  verdict_why_not: median.verdict_why_not,
  verdict_set_at: new Date().toISOString(),
  disqualifier_checks: disqualifierChecks,
  gap_items: gapItems,
  compliance_items: complianceItems,
  questions: (median.questions || []).map((q) => ({ lane: q.lane, question_text: q.question_text })),
};

return [
  {
    json: {
      body,
      bid_desk_url: prompt.bid_desk_url,
      runs: parsed.length,
      failed_runs: failures.length,
      samples,
      spread,
      dissent,
    },
  },
];

// Turns a Gmail message into the same payload shape the webhook accepts, so
// everything downstream of Config is identical for both entry points.
//
// Preference order for what actually gets triaged:
//   1. A linked PDF  — the solicitation itself, the only authoritative source.
//   2. A portal/bid link — likely to resolve to the solicitation.
//   3. The email body — a fallback. Aggregator summaries paraphrase, and their
//      dollar estimates are often well off the real not-to-exceed figure, so a
//      verdict built from one is weaker. Flagged so it is visible downstream.

const LINK_NOISE = /unsubscribe|list-manage|mailchimp|sendgrid|sparkpost|hubspot|googleusercontent|\.gif|\.png|\.jpg|mailto:|utm_|\/track\/|click\.|email\./i;
const PORTALish = /bid|solicit|procure|rfp|rfq|opportunit|contract|planetbids|bidnet|bonfire|periscope|demandstar|sam\.gov/i;

function urlsIn(text) {
  const found = text.match(/https?:\/\/[^\s"'<>)\]]+/g) || [];
  return found
    .map((u) => u.replace(/[.,;:]+$/, ""))
    .filter((u) => !LINK_NOISE.test(u));
}

const out = [];

for (const item of $input.all()) {
  const m = item.json;

  const subject = (m.subject || "(no subject)").trim();
  const bodyText = m.text || m.textPlain || m.snippet || "";
  const bodyHtml = m.html || m.textHtml || "";
  const haystack = `${bodyText}\n${bodyHtml}`;

  // Gmail hands attachments over as binary on the item. Pick the first one
  // that looks like a solicitation rather than the first one full stop -
  // inline logos and signature images arrive as attachments too.
  const DOCUMENT_FILE = /\.(pdf|docx?|rtf)$/i;
  const binaries = Object.entries(item.binary || {});
  const attached = binaries.find(([, b]) =>
    DOCUMENT_FILE.test(b.fileName || '') ||
    /pdf|wordprocessingml|msword/i.test(b.mimeType || '')
  );

  const links = urlsIn(haystack);
  const pdf = links.find((u) => /\.pdf(\?|$)/i.test(u));
  const portal = links.find((u) => PORTALish.test(u));
  const chosen = pdf || portal || null;

  // Gmail's message id is stable and unique, so re-processing the same email
  // upserts the same RFP row rather than creating a duplicate.
  const externalId = `gmail-${m.id || m.messageId || Date.now()}`;

  const payload = {
    // Set when the solicitation came attached rather than linked. The branch
    // after Config reads this to send the bytes for extraction.
    attachment_field: attached ? attached[0] : null,
    attachment_name: attached ? attached[1].fileName || null : null,
    external_id: externalId,
    source: "email",
    source_url: chosen || undefined,
    email_subject: subject,
    email_from: m.from?.value?.[0]?.address || m.From || null,
  };

  if (chosen) {
    payload.document_url = chosen;
  } else {
    payload.document_text = [
      `Subject: ${subject}`,
      "",
      bodyText || "(no plain-text body)",
      "",
      "[NOTE FOR TRIAGE: no solicitation link was found in this email, so the",
      "text above is an aggregator summary rather than the solicitation itself.",
      "Treat any budget figure as unconfirmed unless the RFP is attached, and",
      "prefer 'maybe' over a confident verdict where the summary is thin.]",
    ].join("\n");
  }

  out.push({ json: { body: payload } });
}

return out;

// Module 10. Builds the Drive destination from the verdict, using the naming
// convention the SOW fixes:
//   [Engagement]_[Client]_Caravann Consulting
//
// The title and client come from the reconcile step, not from this node's own
// input. The input here is the bid desk's *response*, which is only
// { id, status } — so reading v.title off it silently produced undefined and
// every folder in Drive came out named "__Caravann Consulting". Nothing threw;
// two empty strings just collapsed into their separators. The verdict still has
// to come from the response, because it is recomputed server-side and the
// model's own label is discarded — so both sources are genuinely needed.
const clean = (s) => String(s || '').replace(/[\\/:*?"<>|]/g, '').replace(/\s+/g, ' ').trim();
// Reconcile returns { body, bid_desk_url, samples, ... } — the solicitation
// fields live under `body`, which is what gets POSTed to the bid desk.
const triaged = $('Reconcile triage runs').first().json.body || {};

return $input.all().map((item) => {
  const v = item.json;
  const verdict = v.status || 'pending';
  const folder = verdict === 'no_go' ? 'no-go' : verdict === 'maybe' ? 'maybe' : 'go';
  const title = clean(v.title || triaged.title);
  const client = clean(v.client_agency || triaged.client_agency);
  // Join only the parts that exist, so a missing client gives a usable name
  // rather than a stack of separators.
  const base = [title, client, 'Caravann Consulting'].filter(Boolean).join('_');
  return {
    json: {
      ...v,
      drive_parent_folder: `/RFPs/${folder}/`,
      // Prefixes the verdict lane onto the folder name. The designed layout
      // was /RFPs/<lane>/<name>, but the Drive node takes a parent ID and
      // cannot create intermediate folders, so the lane rides in the name
      // until a real tree exists.
      drive_lane: `[${folder}] `,
      drive_subfolder: base,
      drive_file_base: base,
    },
  };
});

// The attachment is now plain text. Put it back on the payload as
// document_text and hand it on, so an attached solicitation and a pasted one
// travel the same path from here.
const original = $('Email → intake payload').first().json;
const extracted = $input.first().json;

const text = (extracted.text || '').trim();
if (!text) {
  throw new Error(`Attachment ${original.payload.attachment_name || ''} produced no readable text.`);
}

return [{
  json: {
    ...original,
    payload: {
      ...original.payload,
      document_text: text,
      // The link, if there was one, is no longer what gets read - but it is
      // still the best thing to show as the source on the card.
      document_url: undefined,
    },
  },
}];
